function solve({config,state,event}){
  function has(o,k){return Object.prototype.hasOwnProperty.call(o,k)}
  function copy(o){var r={};for(var k of Object.keys(o))r[k]=o[k];return r}
  function cmp(a,b){var x=Array.from(a),y=Array.from(b),n=Math.min(x.length,y.length);for(var i=0;i<n;i++){var d=x[i].codePointAt(0)-y[i].codePointAt(0);if(d)return d}return x.length-y.length}
  if(state===null)state={version:0,capacity:config.capacity,values:copy(config.initial)}
  var values=state.values,g=event.guards,u=event.updates,invalid=false,k
  for(k of Object.keys(g))if(!has(values,k))invalid=true
  for(k of Object.keys(u))if(!has(values,k)||!has(g,k)||u[k]<0)invalid=true
  var status,version=state.version,changed=[]
  if(invalid)status='invalid'
  else if(event.version!==version)status='stale'
  else{
    status='unchanged'
    for(k of Object.keys(g))if(values[k]!==g[k]){status='conflict';break}
    if(status==='unchanged'){
      var candidate=copy(values),sum=0
      for(k of Object.keys(u))candidate[k]=u[k]
      for(k of Object.keys(candidate))sum+=candidate[k]
      if(sum>state.capacity)status='capacity'
      else{
        for(k of Object.keys(values))if(candidate[k]!==values[k])changed.push(k)
        changed.sort(cmp)
        if(changed.length){values=candidate;version++;status='committed'}
      }
    }
  }
  state={version:version,capacity:state.capacity,values:values}
  if(status!=='committed')changed=[]
  return {state:state,output:{status:status,version:version,values:copy(values),changed:changed}}
}
